// UNS сэдвээс шатлалыг гаргаж авна
// cnc302/<site>/<area>/<line>/<device>/telemetry
// Гаралт: 1 = телеметр, 2 = data_integrity.py-ийн мессеж, 3 = dead-letter
const dead = (reason) => [null, null, { payload: JSON.stringify({
    ts: Date.now(), stage: 'parse', reason, topic: msg.topic,
    raw: (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload) }) }];

const p = msg.topic.split('/');
if (p.length !== 6) { node.warn('UNS схем зөрчсөн: ' + msg.topic); return dead('uns'); }
let d = msg.payload;
if (typeof d !== 'object' || d === null) {
    try { d = JSON.parse(d); } catch (e) { return dead('json'); }
}
msg.tags = { site: p[1], area: p[2], line: p[3], device: p[4] };
msg.rx_ms = Date.now();          // Node-RED хүлээн авсан цаг (MTTR-д)
msg.payload = d;

// Лаб 5-ын бүрэн бүтэн байдлын мессеж: {run_id, seq, ts, value}
if (d.run_id !== undefined && Number.isInteger(d.seq)) {
    return [null, msg, null];
}

// Өгөгдлийн чанарын шалгуур — хүрээнээс гарсныг санд оруулахгүй
// (симулятор: temperature, ирмэгийн агент: proc_temp_c)
for (const k of ['temperature', 'proc_temp_c']) {
    if (typeof d[k] === 'number' && (d[k] < -60 || d[k] > 150)) {
        node.warn(k + ' хүрээнээс гарсан: ' + d[k]);
        return dead('range:' + k);
    }
}
return [msg, null, null];

// Төхөөрөмж тус бүрээр 60 секундын гулсах цонх
const key = msg.tags.device;
const now = Date.now();
// Төхөөрөмжийн нэрийг context-ийн түлхүүр болгож болохгүй (зай, цэг)
// тул бүх цонхыг нэг объектод хадгална.
const all = flow.get('windows') || {};
let w = all[key] || [];
const v = (typeof msg.payload.temperature === 'number') ? msg.payload.temperature : msg.payload.proc_temp_c;
if (typeof v !== 'number') return null;   // температургүй мессеж
w.push({ t: now, v });
w = w.filter(x => now - x.t <= 60000);
all[key] = w;
flow.set('windows', all);

if (w.length < 5) return null;   // хангалттай дээж цуглах хүртэл

const vals = w.map(x => x.v);
const avg = vals.reduce((a,b)=>a+b,0) / vals.length;
return {
    topic: 'agg',
    tags: msg.tags,
    payload: {
        avg_temperature: Number(avg.toFixed(3)),
        min_temperature: Math.min(...vals),
        max_temperature: Math.max(...vals),
        samples: vals.length
    }
};

// InfluxDB line protocol болгож хөрвүүлнэ.
// Tag утгад таслал, тэнцүү, зай → \ -ээр escape (line protocol-ын дүрэм).
// Талбар: тоо → float, boolean → true/false. ts, seq, текст талбарыг алгасна.
const t = msg.tags, d = msg.payload;
const esc = s => String(s).replace(/[ ,=]/g, '\\$&');
const tags = `site=${esc(t.site)},area=${esc(t.area)},line=${esc(t.line)},device=${esc(t.device)}`;
const f = [];
for (const [k, v] of Object.entries(d)) {
    if (k === 'ts' || k === 'seq') continue;
    if (typeof v === 'number' && Number.isFinite(v)) f.push(`${esc(k)}=${v}`);
    else if (typeof v === 'boolean') f.push(`${esc(k)}=${v}`);
}
if (f.length === 0) return null;               // бичих талбаргүй
const ts = Number.isInteger(d.ts) ? d.ts : Date.now();   // мс (precision=millisecond)
msg.payload = `telemetry,${tags} ${f.join(',')} ${ts}`;
msg.lp = msg.payload;                          // dead-letter-т хадгалахад
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
return msg;

// data_integrity.py-ийн мессежийг `integrity` хүснэгтэд бичнэ.
// Нэг цэг = хүснэгт + tag set + цаг. QoS 1-ийн давхар хүргэлт ижил
// (run_id, device, ts)-тэй тул НЭГ цэг болж нийлнэ.
const t = msg.tags, d = msg.payload;
const esc = s => String(s).replace(/[ ,=]/g, '\\$&');
const ts = Number.isInteger(d.ts) ? d.ts : msg.rx_ms;
const value = (typeof d.value === 'number') ? `,value=${d.value}` : '';
msg.payload = `integrity,run_id=${esc(d.run_id)},device=${esc(t.device)} seq=${d.seq}i${value},rx_ms=${msg.rx_ms}i ${ts}`;
msg.lp = msg.payload;
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
return msg;

const t = msg.tags, d = msg.payload;
const esc = s => String(s).replace(/[ ,=]/g, '\\$&');
const tags = `site=${esc(t.site)},area=${esc(t.area)},line=${esc(t.line)},device=${esc(t.device)}`;
const fields = `avg_temperature=${d.avg_temperature},min_temperature=${d.min_temperature},max_temperature=${d.max_temperature},samples=${d.samples}i`;
msg.payload = `telemetry_1m,${tags} ${fields} ${Date.now()}`;
msg.lp = msg.payload;
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
return msg;

// InfluxDB 3 амжилттай бичилтэд 204 буцаана. Бусад нь алдаа:
// 400 = line protocol/төрлийн зөрчил, 401/403 = токен, эсвэл холболтын
// алдааны код (ECONNREFUSED, ENOTFOUND …) — InfluxDB унтарсан үед.
const code = msg.statusCode;
if (code !== 204) {
    const n = (flow.get('write_errors') || 0) + 1;
    flow.set('write_errors', n);
    node.status({fill:'red', shape:'ring', text: `алдаа ${n}: ${code}`});
    node.warn(`InfluxDB бичилт амжилтгүй ${code}: ${String(msg.payload).slice(0, 200)}`);
    return [null, { payload: JSON.stringify({ ts: Date.now(), stage: 'write',
        statusCode: code, error: String(msg.payload).slice(0, 500), lp: msg.lp }) }];
}
const ok = (flow.get('write_ok') || 0) + 1;
flow.set('write_ok', ok);
node.status({fill:'green', shape:'dot', text: `бичсэн ${ok}`});
return [msg, null];

const ok = flow.get('write_ok') || 0;
const err = flow.get('write_errors') || 0;
node.status({fill: err ? 'yellow':'green', shape:'dot', text:`ok=${ok} алдаа=${err}`});
return { payload: { write_ok: ok, write_errors: err, ts: Date.now() } };
